#!/usr/bin/env node
// Regenerates the files derived from app.yaml.
//
//   npm run app:sync              write them
//   npm run app:sync -- --check   exit 1 if any is out of date (CI runs this)
//   npm run app:sync -- --list    show the generated files and the derived values
//
// Two kinds of output:
//   - GENERATED_FILES are written whole and carry a "do not edit" header.
//   - Managed lines in hand-written files end with `# app:sync <key>`; only the value
//     before that comment is replaced, with the derived value named by <key>. Every
//     tracked file containing such a tag is managed (see managedFiles).
//   - The <title> and robots meta in src/index.html, so the raw page names the app and
//     stays out of search results until app.yaml says it has launched.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse, stringify } from 'yaml';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

export const FAMILIES = {
  alphasynthesis: {
    namespace: 'alphasynthesis',
    prodDomain: 'platform.moleculemaker.org',
    feedbackDomain: 'moleculemaker.org',
  },
  alphasynbio: {
    namespace: 'ibiofoundry',
    prodDomain: 'platform.ibiofoundry.illinois.edu',
    feedbackDomain: 'ibiofoundry.illinois.edu',
  },
};

const BACKEND = {
  staging: 'https://mmli.fastapi.staging.mmli2.ncsa.illinois.edu',
  prod: 'https://mmli.fastapi.mmli2.ncsa.illinois.edu',
};
const AUTH = {
  staging: 'https://mmli2.ncsa.illinois.edu/oauth2',
  prod: 'https://auth.platform.moleculemaker.org/oauth2',
};

// Leaves room for the longest derived name, `<id>-prod-domain-redirect`, within a
// 63-character DNS label / Kubernetes name
const MAX_ID_LENGTH = 40;

const TAG = /#\s*app:sync\b/;

const gitGrep = (args) => execFileSync('git', ['grep', ...args], { cwd: ROOT, encoding: 'utf8' });

// Every file with a tag (tracked, or untracked and not ignored), so a tag can't be
// added somewhere that sync ignores. scripts/ and docs are excluded because they
// describe the tag rather than use it.
export function managedFiles(grep = gitGrep) {
  try {
    return grep(['--untracked', '-l', '-E', '#[[:space:]]*app:sync', '--', '.', ':!scripts', ':!*.md'])
      .split('\n').filter(Boolean);
  } catch (err) {
    if (err.status === 1) return []; // git grep's "no matches"
    throw err;
  }
}

export function validate(app) {
  const errors = [];
  if (typeof app?.id !== 'string' || !/^[a-z][a-z0-9-]*[a-z0-9]$/.test(app.id)) {
    errors.push('id must be a lowercase slug (letters, digits, hyphens), e.g. ezkinetics');
  } else if (app.id.length > MAX_ID_LENGTH) {
    errors.push(`id must be at most ${MAX_ID_LENGTH} characters (it becomes DNS labels and Kubernetes names)`);
  }
  if (typeof app?.name !== 'string' || !app.name.trim()) errors.push('name is required');
  if (!FAMILIES[app?.family]) {
    errors.push(`family must be one of: ${Object.keys(FAMILIES).join(', ')}`);
  }
  if (!Number.isInteger(app?.matomo_site_id)) errors.push('matomo_site_id must be an integer');
  if (typeof app?.launched !== 'boolean') errors.push('launched must be true or false');
  return errors;
}

export function derive(app) {
  const family = FAMILIES[app.family];
  const stagingHost = `${app.id}.frontend.staging.mmli2.ncsa.illinois.edu`;
  const prodHost = `${app.id}.${family.prodDomain}`;
  return {
    namespace: family.namespace,
    local_host: `${app.id}.proxy.localhost`,
    staging_host: stagingHost,
    prod_host: prodHost,
    // The cluster's own name for the prod app, redirected to prod_host
    prod_alias_host: `${app.id}.frontend.mmli2.ncsa.illinois.edu`,
    // Docker Hub for every family until the template moves to ghcr (#13)
    image: `moleculemaker/${app.id}-frontend`,
    feedback_email: `${app.id}-feedback@${family.feedbackDomain}`,
  };
}

// `environment` drives the internal-testing banner: anything but prod shows it,
// linking to `prodUrl`
function runtimeConfig(auth, environment, host, backend, prodHost) {
  const rd = encodeURIComponent(`https://${host}/configuration`);
  return {
    hostname: backend,
    basePath: '',
    signInUrl: `${AUTH[auth]}/start?rd=${rd}`,
    signOutUrl: `${AUTH[auth]}/sign_out?rd=${rd}`,
    userInfoUrl: `${AUTH[auth]}/userinfo`,
    frontendOnly: 'false',
    environment,
    prodUrl: `https://${prodHost}`,
  };
}

const TLS_ANNOTATIONS = {
  'cert-manager.io/cluster-issuer': 'letsencrypt-production',
  'kubernetes.io/tls-acme': 'true',
  'traefik.ingress.kubernetes.io/router.tls': 'true',
};

const YAML_HEADER = '# Generated by `npm run app:sync` from app.yaml. Do not edit.\n';
const toYaml = (value) => YAML_HEADER + stringify(value, { lineWidth: 0 });

export function render(app) {
  const d = derive(app);
  const redirect = `${app.id}-prod-domain-redirect`;
  return {
    'src/app/app-identity.ts': [
      '// Generated by `npm run app:sync` from app.yaml. Do not edit.',
      'export const APP_IDENTITY = {',
      `  id: ${JSON.stringify(app.id)},`,
      `  name: ${JSON.stringify(app.name)},`,
      `  family: ${JSON.stringify(app.family)},`,
      `  matomoSiteId: ${app.matomo_site_id},`,
      `  feedbackEmail: ${JSON.stringify(d.feedback_email)},`,
      '} as const;',
      '',
    ].join('\n'),

    'chart/Chart.yaml': toYaml({
      apiVersion: 'v2',
      description: `${app.name} frontend`,
      name: `${app.id}-frontend`,
      version: '1.0.0',
      dependencies: [{ name: 'common', version: '~2.2.0', repository: 'https://charts.bitnami.com/bitnami' }],
    }),

    // Local cluster defaults; staging and prod override all of it
    'chart/values.yaml': toYaml({
      ingress: { hostname: d.local_host, tls: false, annotations: {} },
      controller: { image: d.image },
      config: runtimeConfig('staging', 'local', d.local_host, BACKEND.staging, d.prod_host),
      extraDeploy: [],
    }),

    'chart/values.staging.yaml': toYaml({
      ingress: { hostname: d.staging_host, tls: true, annotations: TLS_ANNOTATIONS },
      controller: { image: `${d.image}:staging` },
      config: runtimeConfig('staging', 'staging', d.staging_host, BACKEND.staging, d.prod_host),
    }),

    'chart/values.prod.yaml': toYaml({
      ingress: {
        hostname: d.prod_host,
        extraHosts: [d.prod_alias_host],
        tls: true,
        annotations: {
          ...TLS_ANNOTATIONS,
          'traefik.ingress.kubernetes.io/router.middlewares': `${d.namespace}-${redirect}@kubernetescrd`,
        },
      },
      controller: { image: `${d.image}:main` },
      config: runtimeConfig('prod', 'prod', d.prod_host, BACKEND.prod, d.prod_host),
      extraDeploy: [{
        apiVersion: 'traefik.io/v1alpha1',
        kind: 'Middleware',
        metadata: { name: redirect, namespace: d.namespace },
        spec: {
          redirectRegex: {
            regex: `^https://${d.prod_alias_host}/(.*)`,
            replacement: `https://${d.prod_host}/\${1}`,
            permanent: true,
          },
        },
      }],
    }),
  };
}

// `key: value # app:sync k`, `- value # app:sync k` or `- key: value # app:sync k`
const MANAGED_LINE = /^(\s*(?:- (?:[\w-]+: )?|[\w-]+: ))(\S.*?)(\s+# app:sync ([\w]+))$/;

export function updateManagedLines(text, derived, file) {
  return text.split('\n').map((line, i) => {
    if (!TAG.test(line)) return line;
    const m = line.match(MANAGED_LINE);
    // A tagged line that can't be rewritten would otherwise keep a stale value
    // while --check passes
    if (!m) {
      throw new Error(`${file}:${i + 1}: cannot rewrite this app:sync line; use "key: value # app:sync <key>" `
        + 'or "- value # app:sync <key>" on one line. (A comment that only mentions the tag must be reworded.)');
    }
    const key = m[4];
    if (!(key in derived)) throw new Error(`${file}: unknown app:sync key "${key}"`);
    return `${m[1]}${derived[key]}${m[3]}`;
  }).join('\n');
}

const NOINDEX = /\n[ \t]*<meta name="robots" content="noindex" \/>/;

export function updateIndexHtml(html, app) {
  const escaped = app.name.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  const title = /([ \t]*)<title>[^<]*<\/title>/;
  if (!title.test(html)) throw new Error('src/index.html has no <title>');
  // Functions, so `$&` and friends in the name are inserted literally
  let out = html.replace(NOINDEX, () => '');
  // Any other robots tag would survive launch and keep the site out of search
  if (/<meta\b[^>]*\bname=["']robots["']/i.test(out)) {
    throw new Error('src/index.html has a robots meta tag app:sync did not write; remove it '
      + '(indexing is controlled by `launched` in app.yaml)');
  }
  out = out.replace(title, (_, indent) => `${indent}<title>${escaped}</title>`
    + (app.launched ? '' : `\n${indent}<meta name="robots" content="noindex" />`));
  return out;
}

export function outputs(app, readFile) {
  const files = render(app);
  const derived = derive(app);
  for (const file of managedFiles()) {
    files[file] = updateManagedLines(readFile(file), derived, file);
  }
  files['src/index.html'] = updateIndexHtml(readFile('src/index.html'), app);
  return files;
}

function main(argv) {
  const read = (file) => readFileSync(join(ROOT, file), 'utf8');
  const app = parse(read('app.yaml'));
  const errors = validate(app);
  if (errors.length) {
    console.error(`app.yaml is invalid:\n  ${errors.join('\n  ')}`);
    return 1;
  }

  let files;
  try {
    files = outputs(app, read);
  } catch (err) {
    console.error(err.message);
    return 1;
  }

  if (argv.includes('--list')) {
    console.log('Derived from app.yaml:');
    for (const [key, value] of Object.entries(derive(app))) console.log(`  ${key}: ${value}`);
    console.log('\nGenerated files:');
    for (const file of Object.keys(render(app))) console.log(`  ${file}`);
    console.log('\nFiles with managed lines (# app:sync <key>):');
    for (const file of managedFiles()) console.log(`  ${file}`);
    console.log('  src/index.html (<title>, robots meta)');
    return 0;
  }

  const stale = Object.entries(files)
    .filter(([file, content]) => !existsSync(join(ROOT, file)) || read(file) !== content)
    .map(([file]) => file);

  if (argv.includes('--check')) {
    if (stale.length) {
      console.error(`Out of date with app.yaml (run \`npm run app:sync\`, never edit these by hand):\n  ${stale.join('\n  ')}`);
      return 1;
    }
    console.log('All files derived from app.yaml are up to date.');
    return 0;
  }

  for (const file of stale) writeFileSync(join(ROOT, file), files[file]);
  console.log(stale.length ? `Updated:\n  ${stale.join('\n  ')}` : 'Already up to date.');
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exit(main(process.argv.slice(2)));
}
